def gift_pro(apps, schema_editor):
    """The owner's choice (2026-11-01): a new account gets the Pro plan for
    a month. Found by its slug or name; with no Pro plan, no gift is set and
    the console can pick one. A settings row made here changes nothing else:
    its other fields are the "not set" defaults."""
    Plan = apps.get_model("billing", "Plan")
    BillingSettings = apps.get_model("billing", "BillingSettings")
    plans = Plan.objects.filter(kind="plan", is_free=False).exclude(status="inactive")
    pro = (
        plans.filter(slug__iexact="pro").first()
        or plans.filter(name_en__iexact="pro").first()
        or plans.filter(name_fa__contains="پرو").first()
    )
    if pro is None:
        return
    row = BillingSettings.objects.first() or BillingSettings()
    if row.signup_gift_plan_id is None:
        row.signup_gift_plan = pro
        row.signup_gift_days = 30
        row.save()


